'use client'

import { CombinedGraphQLErrors } from '@apollo/client/errors'
import { useQuery } from '@apollo/client/react'
import Link from 'next/link'
import { useState, type ReactElement, type ReactNode } from 'react'
import { FrameDetailDocument } from '../generated/graphql'
import { HistoryDialog } from './frame-history'
import { frameDetailHref } from './frame-route'
import { errorMessage } from './inventory-api'
import { StatusChip } from './inventory-list'
import { useInventoryActions } from './inventory-workspace'

function DetailFields({ title, fields }: {
  title: string
  fields: ReadonlyArray<readonly [string, ReactNode]>
}): ReactElement {
  return (
    <section className="card detail-card">
      <h2>{title}</h2>
      <dl className="detail-fields">
        {fields.map(([name, value]) => (
          <div key={name}>
            <dt>{name}</dt>
            <dd>{value == null || value === '' ? <span className="subtle">—</span> : value}</dd>
          </div>
        ))}
      </dl>
    </section>
  )
}

export function FrameDetail({ frameId }: { frameId: string }): ReactElement {
  const [showHistory, setShowHistory] = useState(false)
  const { showImports } = useInventoryActions()
  const { data, loading, error, refetch } = useQuery(FrameDetailDocument, {
    variables: { id: frameId },
    fetchPolicy: 'network-only',
    ssr: false,
  })
  const frame = data?.frame
  const attributes = frame?.attributes
  const notFound = (frame === null && !error) || (
    CombinedGraphQLErrors.is(error) &&
    error.errors.every(({ extensions }) => extensions?.code === 'NOT_FOUND')
  )

  return (
    <>
      <Link className="text-button detail-back" href="/">← Back to frames</Link>
      <div className="page-heading detail-heading">
        <h1>{frameId}</h1>
        {frame && (
          <button className="button button-secondary" onClick={() => setShowHistory(true)}>
            Version history
          </button>
        )}
      </div>
      {loading ? (
        <p className="card panel-message" role="status">Loading frame details…</p>
      ) : notFound ? (
        <p className="card panel-message" role="status">Frame not found.</p>
      ) : error || !frame || !attributes ? (
        <div className="card panel-message" role="alert">
          <p className="error">{error ? errorMessage(error) : 'Inventory service returned no result.'}</p>
          <button className="button button-secondary" onClick={() => {
            void refetch().catch(() => undefined)
          }}>
            Try again
          </button>
        </div>
      ) : (
        <div className="detail-grid">
          <DetailFields title="Frame" fields={[
            ['Status', <StatusChip key="status" value={attributes.status} />],
            ['Status reason', attributes.statusReason],
            ['Site number', attributes.siteNo],
            ['Inventory site number', attributes.inventorySiteNo],
            ['Panel number', attributes.panelNumber],
            ['Location ID', attributes.locationId],
            ['Environment', attributes.environment],
          ]} />
          <DetailFields title="Location" fields={[
            ['Address', attributes.address],
            ['Country code', attributes.location?.countryCode],
            ['Region', attributes.location?.region],
            ['Town', attributes.location?.town],
            ['Postcode', attributes.location?.postcode],
            ['Station', attributes.station],
            ['Airport', attributes.airport],
            ['Latitude', attributes.latitude],
            ['Longitude', attributes.longitude],
            ['Distance to closest school', attributes.distanceToClosestSchool == null
              ? null : `${attributes.distanceToClosestSchool} m`],
          ]} />
          <DetailFields title="Format and specifications" fields={[
            ['Technology', attributes.format?.technology],
            ['Format code', attributes.format?.formatCode],
            ['Size group code', attributes.format?.sizeGroupCode],
            ['Size code', attributes.sizeCode],
            ['Aspect ratio code', attributes.aspectRatioCode],
            ['T-size', attributes.tSize],
            ['Pixel height', attributes.pixelHeight],
            ['Pixel width', attributes.pixelWidth],
            ['Illumination type ID', attributes.illuminationTypeId],
            ['Number of slots', attributes.numberOfSlots],
          ]} />
          <DetailFields title="Commercial" fields={[
            ['Impact weight', attributes.impactWeight],
            ['Premium', attributes.premium ? 'Yes' : 'No'],
            ['Production rate card', attributes.productionRateCard],
            ['Legacy production rate card', attributes.productionRateCardLegacy],
            ['Pricing grade', attributes.pricingGrade],
          ]} />
          {frame.externalReferences.length > 0 ? (
            <DetailFields title="External references" fields={
              frame.externalReferences.map(({ key, value }) => [key, value])
            } />
          ) : (
            <section className="card detail-card">
              <h2>External references</h2>
              <p className="subtle">No external references.</p>
            </section>
          )}
          <section className="card detail-card">
            <h2>Linked frames</h2>
            {frame.linkedFrameIds.length > 0 ? (
              <ul className="detail-links">
                {frame.linkedFrameIds.map((id, position) => (
                  <li key={`${position}:${id}`} className="mono">
                    {id === frameId ? id : (
                      <Link className="text-button" href={frameDetailHref(id)}>
                        {id}
                      </Link>
                    )}
                  </li>
                ))}
              </ul>
            ) : <p className="subtle">No linked frames.</p>}
          </section>
        </div>
      )}
      {showHistory && (
        <HistoryDialog
          frameId={frameId}
          onClose={() => setShowHistory(false)}
          onJob={showImports}
        />
      )}
    </>
  )
}
'use client'

import { CombinedGraphQLErrors } from '@apollo/client/errors'
import { skipToken, useMutation, useQuery } from '@apollo/client/react'
import { useEffect, useMemo, useRef, useState, type ReactElement } from 'react'
import { useForm } from 'react-hook-form'
import {
  CreateFrameDocument,
  FrameForEditDocument,
  FramesDocument,
  UpdateFrameDocument,
} from '../generated/graphql'
import {
  FRAME_STATUSES,
  FRAME_TECHNOLOGIES,
  MAX_SLOTS,
  frameFormValues,
  readCreateFrameInput,
  readUpdateFrameInput,
  type FrameFormValues,
} from './frame-form-input'
import { errorMessage, label } from './inventory-api'

export function FrameDialog({
  frameId,
  onClose,
  onSaved,
}: {
  frameId?: string
  onClose: () => void
  onSaved: (frameId: string) => void
}): ReactElement {
  const dialog = useRef<HTMLDialogElement>(null)
  const [conflict, setConflict] = useState(false)
  const details = useQuery(
    FrameForEditDocument,
    frameId === undefined
      ? skipToken
      : {
          variables: { frameId },
          fetchPolicy: 'no-cache',
          ssr: false,
        },
  )
  const [createFrame] = useMutation(CreateFrameDocument, {
    refetchQueries: [FramesDocument],
  })
  const [updateFrame] = useMutation(UpdateFrameDocument, {
    refetchQueries: [FramesDocument],
  })

  const editing = frameId !== undefined
  const current = (details.data ?? details.previousData)?.frame
  const frame = current?.current ? current : undefined
  const values = useMemo(() => frameFormValues(frame), [frame])
  const {
    register,
    handleSubmit,
    reset,
    setError,
    setFocus,
    formState: { errors, isSubmitting: saving },
  } = useForm({ values })
  const submitError = errors.root?.submit?.message
  const fieldsDisabled = saving || details.loading
  const loadError = details.error
    ? errorMessage(details.error)
    : editing && !details.loading && !frame
      ? 'This frame no longer has a current version.'
      : ''

  useEffect(() => {
    const modal = dialog.current
    modal?.showModal()
    if (!editing) setFocus('frameId')
    return () => modal?.close()
  }, [editing, setFocus])

  function cancel(): void {
    if (saving) return
    dialog.current?.close()
    onClose()
  }

  async function reload(): Promise<void> {
    try {
      const { data } = await details.refetch()
      if (data?.frame?.current) {
        setConflict(false)
        reset(frameFormValues(data.frame))
      }
    } catch {
      // The query error is shown in the dialog.
    }
  }

  async function submit(form: FrameFormValues): Promise<void> {
    if (fieldsDisabled || conflict || loadError || (editing && !frame)) return
    const input = frame
      ? { mode: 'edit' as const, result: readUpdateFrameInput(form, frame) }
      : { mode: 'create' as const, result: readCreateFrameInput(form) }
    if ('error' in input.result) {
      setError('root.submit', { message: input.result.error })
      return
    }
    try {
      const saved =
        input.mode === 'edit'
          ? (await updateFrame({ variables: input.result.variables })).data?.updateFrame
          : (await createFrame({ variables: input.result.variables })).data?.createFrame
      if (!saved) throw new Error('Inventory service returned no result.')
      dialog.current?.close()
      onSaved(saved.frameId)
    } catch (error) {
      if (
        editing &&
        CombinedGraphQLErrors.is(error) &&
        error.errors.some(({ extensions }) => extensions?.code === 'CONFLICT')
      ) {
        setConflict(true)
      } else {
        setError('root.submit', { message: errorMessage(error) })
      }
    }
  }

  return (
    <dialog
      ref={dialog}
      className="frame-dialog"
      aria-labelledby="frame-dialog-title"
      onCancel={(event) => {
        event.preventDefault()
        cancel()
      }}
    >
      <header className="drawer-header">
        <h2 id="frame-dialog-title">{editing ? 'Edit frame' : 'Add a frame'}</h2>
        <button
          type="button"
          className="button button-secondary"
          onClick={cancel}
          disabled={saving}
        >
          Cancel
        </button>
      </header>
      {details.loading && !frame && (
        <p className="panel-message" role="status">
          Loading frame…
        </p>
      )}
      {loadError && (
        <div className="panel-message" role="alert">
          <p className="error">{loadError}</p>
          {(!conflict || !frame) && (
            <button
              type="button"
              className="button button-secondary"
              onClick={reload}
              disabled={details.loading}
            >
              Try again
            </button>
          )}
        </div>
      )}
      {(!editing || frame) && (
        <form
          className="frame-form fields"
          onSubmit={(event) => void handleSubmit(submit)(event)}
          aria-busy={fieldsDisabled}
        >
          <fieldset className="fields" disabled={fieldsDisabled}>
            <legend>Basics</legend>
            <label className="field">
              {editing ? 'Frame ID' : 'Frame ID (required)'}
              <input
                {...register('frameId')}
                readOnly={editing}
                required
                maxLength={128}
              />
            </label>
            <div className="field">
              <label htmlFor="frame-status">Status (required)</label>
              <select id="frame-status" {...register('status')} required>
                <option value="" disabled>
                  Choose a status
                </option>
                {FRAME_STATUSES.map((status) => (
                  <option key={status} value={status}>
                    {label(status)}
                  </option>
                ))}
              </select>
            </div>
            <label className="field">
              Status reason
              <input {...register('statusReason')} />
            </label>
            <label className="field">
              Site number
              <input {...register('siteNo')} />
            </label>
            <label className="field">
              Environment
              <input {...register('environment')} />
            </label>
            <label className="field">
              Address
              <input {...register('address')} />
            </label>
          </fieldset>
          <fieldset className="fields" disabled={fieldsDisabled}>
            <legend>Location</legend>
            <p className="subtle">Complete all four fields to add a location.</p>
            <label className="field">
              Country code
              <input {...register('countryCode')} maxLength={2} pattern="[A-Za-z]{2}" placeholder="GB" />
            </label>
            <label className="field">
              Region
              <input {...register('region')} maxLength={128} />
            </label>
            <label className="field">
              Town
              <input {...register('town')} maxLength={128} />
            </label>
            <label className="field">
              Postcode
              <input {...register('postcode')} maxLength={32} />
            </label>
          </fieldset>
          <fieldset className="fields" disabled={fieldsDisabled}>
            <legend>Format</legend>
            <p className="subtle">Complete all three fields to add a format.</p>
            <div className="field">
              <label htmlFor="frame-technology">Technology</label>
              <select id="frame-technology" {...register('technology')}>
                <option value="">Choose a technology</option>
                {FRAME_TECHNOLOGIES.map((technology) => (
                  <option key={technology} value={technology}>
                    {label(technology)}
                  </option>
                ))}
              </select>
            </div>
            <label className="field">
              Format code
              <input {...register('formatCode')} maxLength={128} />
            </label>
            <label className="field">
              Size group code
              <input {...register('sizeGroupCode')} maxLength={128} />
            </label>
          </fieldset>
          <fieldset className="fields" disabled={fieldsDisabled}>
            <legend>Commercial</legend>
            <label className="field">
              Number of slots
              <input
                {...register('numberOfSlots')}
                type="number"
                min={0}
                max={MAX_SLOTS}
                step={1}
              />
            </label>
            <label className="field">
              Impact weight
              <input {...register('impactWeight')} inputMode="decimal" maxLength={128} />
            </label>
            <label className="field">
              Pricing grade
              <input {...register('pricingGrade')} />
            </label>
            <label className="field">
              Production rate card
              <input {...register('productionRateCard')} />
            </label>
            <label className="field">
              Legacy production rate card
              <input {...register('productionRateCardLegacy')} />
            </label>
            <label className="check">
              <input {...register('premium')} type="checkbox" />
              Premium
            </label>
          </fieldset>
          {submitError && (
            <p className="error" role="alert">
              {submitError}
            </p>
          )}
          {conflict && (
            <div className="fields" role="alert">
              <p className="error">
                This frame changed while you were editing. Reload the latest version to continue.
                Your unsaved edits will be replaced.
              </p>
              <div className="actions">
                <button
                  type="button"
                  className="button button-secondary"
                  onClick={reload}
                  disabled={details.loading}
                >
                  {details.loading ? 'Reloading…' : 'Reload latest version'}
                </button>
              </div>
            </div>
          )}
          <div className="actions">
            <button
              type="submit"
              className="button button-primary"
              disabled={fieldsDisabled || conflict || Boolean(loadError)}
            >
              {editing
                ? saving
                  ? 'Saving changes…'
                  : 'Save changes'
                : saving
                  ? 'Creating frame…'
                  : 'Create frame'}
            </button>
          </div>
        </form>
      )}
    </dialog>
  )
}
'use client'

import { usePathname } from 'next/navigation'
import { createContext, useCallback, useContext, useMemo, useState, type ReactElement, type ReactNode } from 'react'
import { FrameDialog } from './frame-dialog'
import { InventoryImport } from './inventory-import'
import { InventoryList } from './inventory-list'

type InventoryActions = {
  showImports: (jobId?: string) => void
  addFrame: () => void
}

const InventoryActionsContext = createContext<InventoryActions | null>(null)

export function useInventoryActions(): InventoryActions {
  const actions = useContext(InventoryActionsContext)
  if (!actions) throw new Error('Inventory actions require the inventory workspace.')
  return actions
}

export function FrameListActions(): ReactElement {
  const { showImports, addFrame } = useInventoryActions()
  return (
    <div className="actions">
      <button className="button button-secondary" onClick={() => showImports()}>
        Import CSV
      </button>
      <button className="button button-primary" onClick={addFrame}>
        Add a frame
      </button>
    </div>
  )
}

export function InventoryWorkspace({ children }: { children: ReactNode }): ReactElement {
  const showList = usePathname() === '/'
  const [area, setArea] = useState<'frames' | 'imports'>('frames')
  const [jobId, setJobId] = useState('')
  const [frameDialog, setFrameDialog] = useState<{ frameId?: string } | null>(null)
  const [savedFrame, setSavedFrame] = useState<{ frameId: string; action: 'created' | 'updated' } | null>(null)
  const showImports = useCallback((id?: string): void => {
    if (id) setJobId(id)
    setArea('imports')
  }, [])
  const actions = useMemo<InventoryActions>(() => ({
    showImports,
    addFrame: () => setFrameDialog({}),
  }), [showImports])

  return (
    <InventoryActionsContext.Provider value={actions}>
      <div className="workspace">
        <header className="workspace-rail">
          <div className="product">
            <span className="product-mark" aria-hidden="true">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8">
                <rect x="3" y="5" width="18" height="14" rx="1" />
                <path d="M3 9h18" />
              </svg>
            </span>
            Frame Inventory
          </div>
          <nav aria-label="Inventory navigation">
            <button
              aria-current={area === 'frames' ? 'page' : undefined}
              onClick={() => setArea('frames')}
            >
              Frames
            </button>
            <button
              aria-current={area === 'imports' ? 'page' : undefined}
              onClick={() => showImports()}
            >
              Imports
            </button>
          </nav>
        </header>
        <main>
          <section hidden={area !== 'frames'}>
            {area === 'frames' && (
              <>
                {children}
                <div hidden={!showList}>
                  {savedFrame && (
                    <p className="card panel-message frame-saved" role="status">
                      Frame <strong>{savedFrame.frameId}</strong> was {savedFrame.action}.
                    </p>
                  )}
                  <InventoryList active={showList} onEdit={(frameId) => setFrameDialog({ frameId })} />
                </div>
                {showList && frameDialog && (
                  <FrameDialog
                    frameId={frameDialog.frameId}
                    onClose={() => setFrameDialog(null)}
                    onSaved={(frameId) => {
                      setSavedFrame({ frameId, action: frameDialog.frameId === undefined ? 'created' : 'updated' })
                      setFrameDialog(null)
                    }}
                  />
                )}
              </>
            )}
          </section>
          <section hidden={area !== 'imports'}>
            <div className="page-heading">
              <div>
                <h1>Imports</h1>
                <p className="subtle">Upload inventory CSV files and review import results.</p>
              </div>
            </div>
            <InventoryImport trackedId={jobId} onTrack={setJobId} />
          </section>
        </main>
      </div>
    </InventoryActionsContext.Provider>
  )
}

